<?php
defined('ABSPATH')||exit;final class SPL_Frontend{
 public function hooks(){add_shortcode('spl_library',array($this,'library'));add_shortcode('spl_upload',array($this,'form'));add_shortcode('spl_saved',array($this,'saved'));add_shortcode('spl_reading_workspace',array($this,'workspace'));add_action('admin_post_spl_submit',array($this,'precheck'),9);add_action('admin_post_spl_submit',array($this,'submit'));add_action('admin_post_spl_stream',array($this,'stream'));add_action('admin_post_nopriv_spl_stream',array($this,'stream'));add_filter('the_content',array($this,'single'),20);add_action('pre_comment_on_post',array($this,'comments'));}
 public function library(){$search=sanitize_text_field(wp_unslash($_GET['library_search']??''));$cat=sanitize_title(wp_unslash($_GET['library_category']??''));$type=sanitize_title(wp_unslash($_GET['document_type']??''));$sort=sanitize_key(wp_unslash($_GET['library_sort']??'latest'));$args=array('post_type'=>SPL_Helpers::TYPE,'post_status'=>'publish','posts_per_page'=>60,'s'=>$search);$tax=array('relation'=>'AND');if(isset(SPL_Helpers::categories()[$cat]))$tax[]=array('taxonomy'=>SPL_Helpers::TAX,'field'=>'slug','terms'=>$cat);if(isset(SPL_Helpers::types()[$type]))$tax[]=array('taxonomy'=>SPL_Helpers::DOCTYPE,'field'=>'slug','terms'=>$type);if(count($tax)>1)$args['tax_query']=$tax;if('read'===$sort){$args['meta_key']='_spl_reads';$args['orderby']='meta_value_num';}elseif('saved'===$sort){$args['meta_key']='_spl_saves';$args['orderby']='meta_value_num';}else$args['orderby']='date';$items=get_posts($args);$featured=get_posts(array('post_type'=>SPL_Helpers::TYPE,'post_status'=>'publish','posts_per_page'=>1,'meta_key'=>'_spl_featured','meta_value'=>'1'));$m=(array)get_option('spl_page_map',array());ob_start();?><main class="spl-shell"><?php echo SPL_Helpers::nav();?><header class="spl-hero"><div><span>Global Digital Reading</span><h1>PDF Library</h1><p>Read responsible books, research, references, and educational documents online.</p></div><form><input name="library_search" value="<?php echo esc_attr($search);?>" placeholder="Search title, author, ISBN, or keywords"><button>Search</button></form></header><?php if($featured):?><section class="spl-featured"><?php echo get_the_post_thumbnail($featured[0],'medium',array('alt'=>$featured[0]->post_title));?><div><span>Featured Document</span><h2><a href="<?php echo esc_url(get_permalink($featured[0]));?>"><?php echo esc_html($featured[0]->post_title);?></a></h2><p><?php echo esc_html($featured[0]->post_excerpt);?></p></div></section><?php endif;?><nav class="spl-categories"><a href="<?php echo esc_url(remove_query_arg('library_category'));?>">All</a><?php foreach(SPL_Helpers::categories()as$k=>$v):?><a href="<?php echo esc_url(add_query_arg('library_category',$k));?>"><?php echo esc_html($v);?></a><?php endforeach;?></nav><form class="spl-filters"><input type="hidden" name="library_search" value="<?php echo esc_attr($search);?>"><select name="document_type"><option value="">All document types</option><?php foreach(SPL_Helpers::types()as$k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($type,$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select><select name="library_category"><option value="">All categories</option><?php foreach(SPL_Helpers::categories()as$k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($cat,$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select><select name="library_sort"><option value="latest">Latest</option><option value="read">Most read</option><option value="saved">Most saved</option></select><button>Apply</button><?php if(SPL_Helpers::can_submit()):?><a href="<?php echo esc_url(get_permalink($m['upload']));?>">Upload Library Document</a><?php endif;?></form><div class="spl-grid"><?php foreach($items as$i):echo$this->card($i);endforeach;?></div><p class="spl-disclaimer">Educational information only. Historical and complementary-health documents do not replace current diagnosis, emergency care, or qualified medical advice.</p></main><?php return ob_get_clean();}
 private function card($p){ob_start();?><article class="spl-card"><a class="spl-cover" href="<?php echo esc_url(get_permalink($p));?>"><?php echo get_the_post_thumbnail($p,'medium',array('loading'=>'lazy','alt'=>$p->post_title));?></a><div><span><?php echo esc_html(SPL_Helpers::term($p->ID,SPL_Helpers::DOCTYPE));?></span><h2><a href="<?php echo esc_url(get_permalink($p));?>"><?php echo esc_html($p->post_title);?></a></h2><p><?php echo esc_html(SPL_Helpers::meta($p->ID,'author_name'));?> · <?php echo absint(SPL_Helpers::meta($p->ID,'pages'));?> pages</p></div></article><?php return ob_get_clean();}
 public function form(){if(!is_user_logged_in()||!SPL_Helpers::can_submit())return'<div class="spl-note">Only the Founder, administrators, and fully verified doctors may upload documents.</div>';ob_start();?><main class="spl-shell"><h1>Upload Library Document</h1><form class="spl-form" action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="spl_submit"><?php wp_nonce_field('spl_submit','spl_nonce');?><?php foreach(array('title'=>'Document title','subtitle'=>'Subtitle','author_name'=>'Author name','contributor'=>'Contributor','publication_year'=>'Publication year','edition'=>'Edition','publisher'=>'Publisher','isbn'=>'ISBN','pages'=>'Number of pages','language'=>'Language','keywords'=>'Keywords')as$k=>$v):?><label><?php echo esc_html($v);?><input name="<?php echo esc_attr($k);?>" <?php echo in_array($k,array('title','author_name','pages','language'),true)?'required':'';?>></label><?php endforeach;?><label>Document type<select name="document_type"><?php foreach(SPL_Helpers::types()as$k=>$v):?><option value="<?php echo esc_attr($k);?>"><?php echo esc_html($v);?></option><?php endforeach;?></select></label><label>Category<select name="category"><?php foreach(SPL_Helpers::categories()as$k=>$v):?><option value="<?php echo esc_attr($k);?>"><?php echo esc_html($v);?></option><?php endforeach;?></select></label><label>Cover image<input type="file" name="cover" accept="image/jpeg,image/png,image/webp" required></label><label>PDF file<input type="file" name="pdf" accept="application/pdf" required></label><label class="wide">Short description<textarea name="excerpt" required></textarea></label><label class="wide">Complete description<textarea name="description" required></textarea></label><label class="wide">Table of contents<textarea name="contents"></textarea></label><label class="wide">References<textarea name="references" required></textarea></label><label class="wide">Medical safety notice<textarea name="safety" required></textarea></label><label>Copyright status<select name="copyright_status"><option value="owned">I Own the Copyright</option><option value="permission">I Have Written Permission</option><option value="public-domain">Public Domain</option><option value="open-license">Open License</option><option value="platform">Official Platform Publication</option></select></label><label><input type="checkbox" name="download_allowed" value="1"> Reading and download allowed</label><label class="wide"><input type="checkbox" name="rights" required> I have the legal right to publish this document; it is not an unauthorized scan.</label><label class="wide"><input type="checkbox" name="medical" required> I confirm the medical-safety, patient-privacy, and educational limitations.</label><button>Submit Document</button></form></main><?php return ob_get_clean();}
 public function submit(){if(!is_user_logged_in()||!SPL_Helpers::can_submit())wp_die('Access denied.');check_admin_referer('spl_submit','spl_nonce');$title=sanitize_text_field(wp_unslash($_POST['title']??''));$type=sanitize_title(wp_unslash($_POST['document_type']??''));$cat=sanitize_title(wp_unslash($_POST['category']??''));if(!$title||!isset(SPL_Helpers::types()[$type])||!isset(SPL_Helpers::categories()[$cat])||empty($_POST['rights'])||empty($_POST['medical'])||empty($_FILES['pdf']['tmp_name']))wp_die('Complete all required fields.');$f=$_FILES['pdf'];$max=min(100*MB_IN_BYTES,wp_max_upload_size());if(UPLOAD_ERR_OK!==(int)$f['error']||(int)$f['size']>$max)wp_die('The PDF is invalid or exceeds the upload limit.');$head=file_get_contents($f['tmp_name'],false,null,0,5);$mime=function_exists('mime_content_type')?mime_content_type($f['tmp_name']):'';if('%PDF-'!==$head||!in_array($mime,array('application/pdf','application/x-pdf'),true)||'pdf'!==strtolower(pathinfo($f['name'],PATHINFO_EXTENSION)))wp_die('Only a genuine PDF file is accepted.');$bytes=file_get_contents($f['tmp_name']);$enc=SPL_Helpers::encrypt($bytes);if(false===$enc)wp_die('PDF encryption failed.');$storage=wp_generate_uuid4().'.spl';if(false===file_put_contents(trailingslashit(SPL_Helpers::storage()).$storage,$enc,LOCK_EX))wp_die('Secure storage failed.');$id=wp_insert_post(array('post_type'=>SPL_Helpers::TYPE,'post_status'=>SPL_Helpers::status(),'post_title'=>$title,'post_excerpt'=>sanitize_textarea_field(wp_unslash($_POST['excerpt']??'')),'post_content'=>wp_kses_post(wp_unslash($_POST['description']??'')),'post_author'=>get_current_user_id(),'comment_status'=>'open'));wp_set_object_terms($id,$type,SPL_Helpers::DOCTYPE);wp_set_object_terms($id,$cat,SPL_Helpers::TAX);foreach(array('subtitle','author_name','contributor','publication_year','edition','publisher','isbn','pages','language','keywords','contents','references','safety','copyright_status')as$k)update_post_meta($id,'_spl_'.$k,sanitize_textarea_field(wp_unslash($_POST[$k]??'')));foreach(array('storage_name'=>$storage,'original_name'=>sanitize_file_name($f['name']),'file_size'=>(int)$f['size'],'download_allowed'=>empty($_POST['download_allowed'])?'0':'1','views'=>0,'reads'=>0,'saves'=>0)as$k=>$v)update_post_meta($id,'_spl_'.$k,$v);require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$cover=media_handle_upload('cover',$id,array(),array('test_form'=>false,'mimes'=>array('jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp')));if(!is_wp_error($cover))set_post_thumbnail($id,$cover);$m=(array)get_option('spl_page_map',array());wp_safe_redirect(get_permalink($m['upload']));exit;}
 public function stream(){$id=absint($_GET['document_id']??0);check_admin_referer('spl_stream_'.$id);if(SPL_Helpers::TYPE!==get_post_type($id)||'publish'!==get_post_status($id))wp_die('Document unavailable.');$download=!empty($_GET['download']);if($download&&'1'!==SPL_Helpers::meta($id,'download_allowed','0'))wp_die('Download is not permitted.');$path=trailingslashit(SPL_Helpers::storage()).basename(SPL_Helpers::meta($id,'storage_name'));$bytes=is_file($path)?SPL_Helpers::decrypt(file_get_contents($path)):false;if(false===$bytes)wp_die('The encrypted PDF could not be opened.');nocache_headers();header('Content-Type: application/pdf');header('Content-Disposition: '.($download?'attachment':'inline').'; filename="'.sanitize_file_name(SPL_Helpers::meta($id,'original_name','document.pdf')).'"');header('Content-Length: '.strlen($bytes));echo$bytes;exit;}
 public function single($c){if(!is_singular(SPL_Helpers::TYPE)||!in_the_loop()||!is_main_query())return$c;$id=get_the_ID();update_post_meta($id,'_spl_views',absint(SPL_Helpers::meta($id,'views'))+1);$reader='<div class="spl-reader"><iframe title="PDF reader for '.esc_attr(get_the_title()).'" src="'.esc_url(SPL_Helpers::stream_url($id)).'"></iframe></div>';$meta='<section class="spl-details"><p><b>Author:</b> '.esc_html(SPL_Helpers::meta($id,'author_name')).'</p><p><b>Type:</b> '.esc_html(SPL_Helpers::term($id,SPL_Helpers::DOCTYPE)).'</p><p><b>Pages:</b> '.absint(SPL_Helpers::meta($id,'pages')).'</p><p><b>Language:</b> '.esc_html(SPL_Helpers::meta($id,'language')).'</p></section>';if('1'===SPL_Helpers::meta($id,'download_allowed'))$meta.='<a class="spl-download" href="'.esc_url(SPL_Helpers::stream_url($id,true)).'">Download PDF</a>';$tail=SPL_Interactions::controls($id).'<section class="spl-panel"><h2>Table of Contents</h2><p>'.nl2br(esc_html(SPL_Helpers::meta($id,'contents'))).'</p></section><section class="spl-panel"><h2>References</h2><p>'.nl2br(esc_html(SPL_Helpers::meta($id,'references'))).'</p></section><section class="spl-panel spl-safety"><h2>Medical Safety Notice</h2><p>'.nl2br(esc_html(SPL_Helpers::meta($id,'safety'))).'</p></section>';return$reader.$meta.$c.$tail;}
 public function saved(){return$this->user_items('Saved Documents','save');}public function workspace(){return$this->user_items('Reading Workspace','progress');}private function user_items($title,$type){if(!is_user_logged_in())return'<div>Log in first.</div>';global$wpdb;$ids=$wpdb->get_col($wpdb->prepare("SELECT DISTINCT document_id FROM {$wpdb->prefix}spl_user_data WHERE user_id=%d AND data_type=%s ORDER BY updated_at DESC",get_current_user_id(),$type));$items=get_posts(array('post_type'=>SPL_Helpers::TYPE,'post_status'=>'publish','post__in'=>$ids?:array(0),'posts_per_page'=>100));$out='<main class="spl-shell"><h1>'.esc_html($title).'</h1>';foreach($items as$i)$out.=$this->card($i);return$out.'</main>';}public function comments($id){if(SPL_Helpers::TYPE===get_post_type($id)&&!is_user_logged_in())wp_die('Log in to comment.',array('response'=>403));}
 public function precheck(){check_admin_referer('spl_submit','spl_nonce');$fields=array('title','author_name','excerpt','description','references','safety','language');$text='';foreach($fields as$key){$value=isset($_POST[$key])?wp_strip_all_tags(wp_unslash($_POST[$key])):'';if(!trim($value))wp_die('Complete every required public field.');$text.=' '.$value;}if(preg_match('/[\x{0600}-\x{06FF}\x{0750}-\x{077F}\x{0900}-\x{097F}\x{0400}-\x{04FF}\x{4E00}-\x{9FFF}\x{3040}-\x{30FF}]/u',$text))wp_die('This release accepts American English public content only.');$cat=sanitize_title(wp_unslash($_POST['category']??''));if('platform-publications'===$cat&&!SPL_Helpers::founder()&&!current_user_can('manage_pdf_library'))wp_die('Platform Publications is reserved for official publishing.');if('patient-cases'===$cat&&empty($_POST['patient_case']))wp_die('Patient Case documents require anonymity and valid consent confirmation.');$key='spl_submit_'.get_current_user_id();if(absint(get_transient($key))>=10)wp_die('Please wait before submitting another document.');set_transient($key,absint(get_transient($key))+1,HOUR_IN_SECONDS);}
}
